/* Reference-based rules. No device detection, benchmark, or FPS estimation. */
const compatibilityRules=Object.freeze({
 memory(ram,minimum=6){if(ram===null||!Number.isFinite(ram))return {level:'unknown',label:'Unverified',title:'Memory data not verified',note:'No verified RAM value is available for this profile. A compatibility conclusion cannot be made.'};if(ram<minimum)return {level:'critical',label:'Critical',title:'Below the reference memory minimum',note:`${ram} GB installed RAM is below the ${minimum} GB reference minimum. Memory pressure may cause missing assets or app termination.`};if(ram===minimum)return {level:'minimum',label:'Minimum',title:'At the reference memory minimum',note:'Limited memory headroom. Start with conservative settings and follow the release instructions.'};return {level:'headroom',label:'Above minimum',title:'Above the reference memory minimum',note:'More installed memory than the reference minimum. This does not guarantee performance or available app memory.'}},
 entry(raw,minimum,unit){if(raw===''||raw===null||raw===undefined)return {level:'unknown',label:'Not checked',value:'Not provided',note:'Enter the value from your iPhone Settings to include this check.'};const value=Number(raw);if(!Number.isFinite(value)||value<0)return {level:'unknown',label:'Invalid entry',value:'Check your entry',note:'Enter a valid non-negative number.'};return value<minimum?{level:'critical',label:'Below baseline',value:unit==='iOS'?'iOS '+value:value+' GB free',note:`The reference baseline is ${unit==='iOS'?'iOS '+minimum+' or later':'approximately '+minimum+' GB free'}.`}:{level:'headroom',label:'Meets baseline',value:unit==='iOS'?'iOS '+value:value+' GB free',note:'Based on the value you entered. The browser has not verified it.'}}
});
if(typeof module!=='undefined'&&module.exports)module.exports=compatibilityRules;
